function icelandNow(){const p=Object.fromEntries(new Intl.DateTimeFormat("en-CA",{timeZone:"Atlantic/Reykjavik",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"}).formatToParts(new Date()).filter(x=>x.type!=="literal").map(x=>[x.type,x.value]));return{date:`${p.year}-${p.month}-${p.day}`,time:`${p.hour}:${p.minute}`,min:(+p.hour*60)+(+p.minute)}}
function decisionState(n,x){const list=(x.cutoffs||[]).filter(c=>timeMin(c.time)!==null).sort((a,b)=>timeMin(a.time)-timeMin(b.time)),now=icelandNow();if(!list.length){if(x.cutoffsReady)return{key:"none",label:"NESSUNA SOGLIA CRITICA",clock:now.time,main:x.cutoffEmpty||"Giornata flessibile.",next:"Segui programma, meteo e condizioni reali."};return{key:"draft",label:"DA VALIDARE",clock:now.time,main:"Soglie orarie in attesa del ricalcolo percorsi.",next:"La logica è pronta: inseriremo tempi e azioni solo dopo la verifica definitiva."}}if(now.date!==tripDates[n]){const f=list[0];return{key:"normal",label:"PROGRAMMATO",clock:now.time,main:`Prima soglia · <b>${f.time}</b>`,next:`${f.condition||""}${f.action?` → ${f.action}`:""}`}}const passed=list.filter(c=>timeMin(c.time)<=now.min),latest=passed.at(-1),upcoming=list.find(c=>timeMin(c.time)>now.min);if(!latest){const f=list[0];return{key:"normal",label:"NORMALE",clock:now.time,main:`Prossima soglia · <b>${f.time}</b>`,next:`${f.condition||""}${f.action?` → ${f.action}`:""}`}}if(latest.level==="direct")return{key:"direct",label:"DIRETTO",clock:now.time,main:latest.action||"Nessun'altra sosta opzionale.",next:latest.condition?`${latest.condition} · ultima soglia superata`:"Ultima soglia superata"};return{key:"reduce",label:"RIDUCI",clock:now.time,main:`Soglia delle <b>${latest.time}</b> superata`,next:`${latest.condition?`${latest.condition} → `:""}${latest.action||"Ridurre il programma"}${upcoming?` · prossima ${upcoming.time}`:""}`}}
function decisionMarkup(n,x){const s=decisionState(n,x),hasChecks=Array.isArray(x.checks)&&x.checks.length>0,hasCutoffs=(x.cutoffs||[]).length>0;return`<div class="decision-top"><div><div class="decision-kicker">Stato giornata</div><div class="decision-state">${s.label}</div></div><div class="decision-clock">Ora Islanda ${s.clock}</div></div><div class="decision-main">${s.main}</div><div class="decision-next">${s.next}</div>${hasChecks||hasCutoffs?`<button type="button" class="decision-more">${hasChecks?"Soglie e controlli":"Vedi tutte le soglie"} ▾</button>`:""}`}
function decisionCard(n,x){const e=document.createElement("div"),s=decisionState(n,x);e.className=`decision-card state-${s.key} trip-enhancement`;e.dataset.day=String(n);e.innerHTML=decisionMarkup(n,x);e.querySelector(".decision-more")?.addEventListener("click",()=>openCutoffs(n,x));return e}
function openCutoffs(n,x){document.querySelector(".cutoff-overlay")?.remove();const o=document.createElement("div"),list=(x.cutoffs||[]).filter(c=>timeMin(c.time)!==null).sort((a,b)=>timeMin(a.time)-timeMin(b.time)),checks=Array.isArray(x.checks)?x.checks:[];const checkHtml=checks.length?`<div class="cutoff-section-title">Controlli non orari</div>${checks.map(c=>`<div class="cutoff-check"><strong>${c.title||"Controllo"}</strong><span>${c.text||""}</span></div>`).join("")}`:"";const cutoffHtml=list.length?`<div class="cutoff-section-title">Soglie orarie</div>${list.map((c,i)=>`<div class="cutoff-row"><div class="cutoff-time">${c.time}</div><div><div class="cutoff-condition">${c.condition||`Soglia ${i+1}`}</div><div class="cutoff-action">${c.action||"Azione da definire"}</div></div></div>`).join("")}`:`<div class="cutoff-empty">Nessuna soglia oraria critica per questa giornata.</div>`;o.className="cutoff-overlay";o.innerHTML=`<div class="cutoff-sheet" role="dialog" aria-modal="true"><div class="cutoff-handle"></div><div class="cutoff-head"><strong>Soglie di taglio · Giorno ${n}</strong><button type="button" class="cutoff-close">Chiudi</button></div>${checkHtml}${cutoffHtml}<div class="cutoff-note">A6 usa sempre l'ora ufficiale islandese — Atlantic/Reykjavik (GMT/UTC+0) — indipendentemente dal fuso impostato sul telefono. Non usa GPS: le condizioni logistiche, stradali e meteo vanno confermate sul posto.</div></div>`;document.body.appendChild(o);const close=()=>o.remove();o.querySelector(".cutoff-close")?.addEventListener("click",close);o.addEventListener("click",ev=>{if(ev.target===o)close()})}
function stickyMarkup(n,x){const s=decisionState(n,x),now=icelandNow(),list=(x.cutoffs||[]).filter(c=>timeMin(c.time)!==null).sort((a,b)=>timeMin(a.time)-timeMin(b.time));let next="";if(list.length){const u=now.date===tripDates[n]?list.find(c=>timeMin(c.time)>now.min):list[0];next=u?` · ${u.time}`:""}return`<div class="day-sticky-main">G${n} · ${x.titolo||x.sub||"Giornata"}</div><div class="day-sticky-state">${s.label}${next}</div>`}
function stickyBar(n,x){const e=document.createElement("div");e.className="day-sticky trip-enhancement";e.dataset.day=String(n);e.innerHTML=stickyMarkup(n,x);return e}
function card(x){const e=document.createElement("div"),v=[];e.className="lodging-card trip-enhancement";if(x.co)v.push(`<div><b>Check-out:</b> ${x.co}</div>`);if(x.p)v.push(`<div><b>Tel:</b> ${x.p}</div>`);if(x.pk)v.push(`<div><b>Parcheggio:</b> ${x.pk}</div>`);e.innerHTML=`<button type="button" class="lodging-toggle"><span class="lodging-main"><span class="compact-kicker">Pernottamento</span><span class="compact-title">${x.n}</span></span><span class="compact-summary">${x.ci?`Check-in ${x.ci}`:"Dettagli"}</span><span class="compact-arrow">⌄</span></button><div class="lodging-content"><div class="lodging-address">${x.a}</div><div class="lodging-details">${v.join("")}</div></div>`;e.querySelector(".lodging-toggle")?.addEventListener("click",()=>e.classList.toggle("is-open"));return e}
function fuelCard(n){const f=fuelPlan[n];if(!f)return null;const e=document.createElement("div");e.className="fuel-card trip-enhancement";e.innerHTML=`<div class="fuel-main"><span class="compact-kicker">A7 · Carburante</span><span class="compact-title">${f.station}</span><div class="fuel-when">${f.when}</div><span class="fuel-action">${f.action}</span></div><a class="fuel-map" href="${mapUrl(f.query)}" target="_blank" rel="noopener noreferrer">APRI MAPS</a><div class="fuel-note">${f.note}<br>Budget provvisorio: €75 a persona. Litri e autonomia verranno ricalcolati il 23/09 dopo il check-in dell'auto.</div>`;return e}
function roadCostCard(n){const list=roadCosts[n];if(!Array.isArray(list)||!list.length)return null;const e=document.createElement("div"),tolls=list.filter(x=>x.k==="PEDAGGIO").length;e.className="roadcost-card trip-enhancement";const rows=list.map(x=>`<div class="roadcost-item"><div class="roadcost-name"><div class="roadcost-type">${x.k}</div><div class="roadcost-title">${x.n}</div></div><div class="roadcost-price">${x.p}</div><div class="roadcost-detail"><span class="roadcost-method">${x.m}</span>${x.d?` · ${x.d}`:""}${x.u?`<br><a class="roadcost-link" href="${x.u}" target="_blank" rel="noopener noreferrer">PAGA / INFO ↗</a>`:""}</div></div>`).join("");e.innerHTML=`<button type="button" class="roadcost-toggle"><span><span class="compact-kicker">Costi operativi</span><span class="compact-title">Parcheggi · pedaggi · ingressi</span></span><span class="roadcost-summary">${list.length} voci${tolls?` · ${tolls} ped.`:""}</span><span class="compact-arrow">⌄</span></button><div class="roadcost-content"><div class="roadcost-list">${rows}</div><div class="roadcost-foot">Tariffe controllate il 12/09/2026. Per importi indicativi o categorie veicolo fa sempre fede il cartello/app sul posto.</div></div>`;e.querySelector(".roadcost-toggle")?.addEventListener("click",()=>e.classList.toggle("is-open"));return e}
function priorityCard(x){const must=Array.isArray(x.must)?x.must:[],bonus=Array.isArray(x.bonus)?x.bonus:[],sac=Array.isArray(x.sac)?x.sac:[];if(!must.length&&!bonus.length&&!sac.length)return null;const e=document.createElement("div");e.className="priority-card trip-enhancement";const group=(label,cls,items)=>`<div class="priority-group ${cls}"><div class="priority-label">${label}</div><ul class="priority-list">${items.length?items.map(v=>`<li>${v}</li>`).join(""):'<li>—</li>'}</ul></div>`;e.innerHTML=`<button type="button" class="priority-toggle"><span class="priority-main"><span class="compact-kicker">Priorità giornata</span><span class="compact-title">Must · Bonus · Sacrificabili</span></span><span class="compact-summary">${must.length} / ${bonus.length} / ${sac.length}</span><span class="compact-arrow">⌄</span></button><div class="priority-content"><div class="priority-grid">${group("Must","must",must)}${group("Bonus","bonus",bonus)}${group("Sacrificabili","sac",sac)}</div></div>`;e.querySelector(".priority-toggle")?.addEventListener("click",()=>e.classList.toggle("is-open"));return e}
function actions(x,l){const e=document.createElement("div");e.className="day-actions trip-enhancement";const route=x.percorsoCompletoMaps||null,items=[["PERCORSO",route,true],["ALLOGGIO",mapUrl(`${l.n}, ${l.a}`),false],["STRADE","https://umferdin.is/en",false],["METEO","https://en.vedur.is/",false]];items.forEach(([label,href,primary])=>{const a=document.createElement(href?"a":"span");a.className=`day-action${primary&&href?" primary":""}${href?"":" disabled"}`;if(href){a.href=href;a.target="_blank";a.rel="noopener noreferrer"}a.textContent=label;e.appendChild(a)});return e}
function next(x){const e=document.createElement("div");e.className="next-morning-card trip-enhancement";e.innerHTML=`<div class="nm-title">Mattina successiva · ${x.date}</div><div><b>Auto:</b> ${x.carReturn}</div><div><b>Volo:</b> ${x.flight}</div><div><b>Partenza hotel:</b> ${x.departure}</div><div><b>Carburante:</b> ${x.fuel}</div><div><b>Check-out:</b> ${x.checkout}</div>`;return e}
function markBooked(b,n){b.querySelectorAll(".booked-badge").forEach(z=>z.remove());(booked[n]||[]).forEach(q=>b.querySelectorAll(".schedule .act-link").forEach(a=>{if((a.textContent||"").toLowerCase().includes(q.toLowerCase())){a.style.fontWeight="700";const badge=document.createElement("span");badge.className="booked-badge";badge.textContent="PRENOTATO";a.insertAdjacentElement("afterend",badge)}}))}
function enhancePackingPanel(listId,progressId,label){const list=document.getElementById(listId),progress=document.getElementById(progressId);if(!list||!progress)return;const p=list.closest(".panel");if(!p||p.dataset.packingEnhanced)return;p.dataset.packingEnhanced="1";p.classList.add("packing-collapsible");const title=p.previousElementSibling;if(title?.classList.contains("section-title"))title.classList.add("packing-title-hidden");const nodes=[...p.childNodes],content=document.createElement("div"),btn=document.createElement("button");content.className="packing-content";nodes.forEach(n=>content.appendChild(n));btn.type="button";btn.className="packing-toggle";btn.innerHTML=`<span><span class="packing-toggle-title">${label}</span><span class="packing-toggle-sub">Tocca per aprire la lista</span></span><span class="packing-count">0 / 0</span><span class="packing-arrow">⌄</span>`;p.append(btn,content);const count=btn.querySelector(".packing-count"),sub=btn.querySelector(".packing-toggle-sub");const update=()=>{const text=(progress.textContent||"0 / 0").match(/\d+\s*\/\s*\d+/)?.[0]||"0 / 0";count.textContent=text;const [done,total]=text.split("/").map(v=>+v.trim());sub.textContent=total&&done===total?"Checklist completa":"Tocca per aprire la lista"};new MutationObserver(update).observe(progress,{childList:true,subtree:true,characterData:true});const key=`islanda_packing_open_${listId}`;const setOpen=open=>{p.classList.toggle("is-open",open);btn.setAttribute("aria-expanded",String(open));sub.textContent=open?"Tocca per chiudere la lista":sub.textContent;try{localStorage.setItem(key,open?"1":"0")}catch{};if(!open)update()};btn.addEventListener("click",()=>setOpen(!p.classList.contains("is-open")));let initial=false;try{initial=localStorage.getItem(key)==="1"}catch{}setOpen(initial);update()}
