function refreshDecisionCards(){if(typeof giorni==="undefined")return;document.querySelectorAll(".decision-card[data-day]").forEach(e=>{const n=+e.dataset.day,x=giorni.find(g=>g.num===n);if(!x)return;const s=decisionState(n,x);e.className=`decision-card state-${s.key} trip-enhancement`;e.innerHTML=decisionMarkup(n,x);e.querySelector(".decision-more")?.addEventListener("click",()=>openCutoffs(n,x))});document.querySelectorAll(".day-sticky[data-day]").forEach(e=>{const n=+e.dataset.day,x=giorni.find(g=>g.num===n);if(x)e.innerHTML=stickyMarkup(n,x)})}
function decorate(){styles();enhancePacking();const c=document.getElementById("daysContainer");if(!c||typeof giorni==="undefined")return;c.querySelectorAll(".day").forEach(el=>{const m=(el.querySelector(".day-num")?.textContent||"").match(/G(\d+)/i);if(!m)return;const n=+m[1],x=giorni.find(g=>g.num===n),l=lod[n],b=el.querySelector(".day-body");if(!x||!l||!b)return;b.querySelectorAll(":scope > .trip-enhancement").forEach(z=>z.remove());markBooked(b,n);const story=b.querySelector(".story");if(story)story.insertAdjacentElement("afterend",stickyBar(n,x));else b.prepend(stickyBar(n,x));const schedule=b.querySelector(".schedule");if(schedule)schedule.insertAdjacentElement("afterend",decisionCard(n,x));const oldMbs=b.querySelector(".mbs");if(oldMbs){oldMbs.classList.add("enhanced-hidden");const pc=priorityCard(x);if(pc)oldMbs.insertAdjacentElement("afterend",pc)}const t=b.querySelector(".trigger"),fc=fuelCard(n),rc=roadCostCard(n);if(fc)b.insertBefore(fc,t||null);if(rc)b.insertBefore(rc,t||null);b.insertBefore(card(l),t||null);if(n===8&&x.nextMorning)b.insertBefore(next(x.nextMorning),t||null);b.insertBefore(actions(x,l),t||null)});if(!decisionTimer)decisionTimer=setInterval(refreshDecisionCards,60000)}
function watch(){const c=document.getElementById("daysContainer");if(!c||obs)return;obs=new MutationObserver(decorate);obs.observe(c,{childList:true});decorate()}
